import React, { useState, useEffect } from "react";
import {
  ResponsiveContainer,
  ScatterChart,
  Scatter,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Radar,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
} from "recharts";
import { HeatMap } from "react-heatmap-grid";

export default function SeedCatalog() {
  const [data, setData] = useState(null);
  const [selected, setSelected] = useState([]);
  const [activeVariety, setActiveVariety] = useState(null);
  const [xTrait, setXTrait] = useState("yield_kg_ha");
  const [yTrait, setYTrait] = useState("maturity_days");

  // GITHUB SAFE LOADING
  useEffect(() => {
    fetch("/seed-catalog/data/uog-varieties.json")
      .then((r) => {
        if (!r.ok) throw new Error("JSON not found");
        return r.json();
      })
      .then((json) => {
        if (!Array.isArray(json))
          throw new Error("JSON is not array");
        setData(json);
      })
      .catch((err) => {
        console.error(err);
        setData([]); // NEVER crash
      });
  }, []);

  // HARD SAFETY GUARD
  if (!Array.isArray(data)) {
    return <div style={{ padding: 40 }}>Loading data…</div>;
  }

  // use name as id
  const selectedRows = data.filter((v) =>
    selected.includes(v.name)
  );

  function toggleSelect(name) {
    setSelected((s) =>
      s.includes(name)
        ? s.filter((x) => x !== name)
        : s.length < 5
        ? [...s, name]
        : s
    );
  }

  function getResistance(v) {
    return {
      CMV_R1: v["Common Mosaic Virus R1"],
      CMV_R15: v["Common Mosaic Virus R15"],
      Anthracnose_R17: v["Anthracnose R17"],
      Anthracnose_R23: v["Anthracnose R23"],
      Anthracnose_R73: v["Anthracnose R73"],
      CommonBlight: v["Common Blight"],
    };
  }

  function resistanceScore(r) {
    const vals = Object.values(r || {}).filter(
      (v) => v && v !== "N/A"
    );
    if (!vals.length) return 0;
    return (
      (vals.filter((v) => v === "R").length /
        vals.length) *
      100
    );
  }

  const diseases = [
    "CMV_R1",
    "CMV_R15",
    "Anthracnose_R17",
    "Anthracnose_R23",
    "Anthracnose_R73",
    "CommonBlight",
  ];

  const heatData = selectedRows.map((v) => {
    const r = getResistance(v);
    return diseases.map((d) => {
      const val = r[d];
      if (val === "R") return 2;
      if (val === "S") return 0;
      return 1;
    });
  });

  const radarData = selectedRows.map((v) => {
    const r = getResistance(v);
    return {
      name: v.name,
      Yield: v.yield_kg_ha ?? 0,
      Maturity: v.maturity_days ?? 0,
      "Seed weight": v.seed_weight_g ?? 0,
      Harvestability: v.harvestability ?? 0,
      Resistance: resistanceScore(r),
    };
  });

  const scatterData = selectedRows
    .filter(
      (v) =>
        typeof v[xTrait] === "number" &&
        typeof v[yTrait] === "number"
    )
    .map((v) => ({
      x: v[xTrait],
      y: v[yTrait],
      name: v.name,
    }));

  return (
    <div style={{ padding: 40 }}>
      <h1>Seed Analytics Dashboard</h1>

      {/* Selector */}
      {data.map((v) => (
        <label key={v.name} style={{ margin: 6 }}>
          <input
            type="checkbox"
            checked={selected.includes(v.name)}
            onChange={() => toggleSelect(v.name)}
          />
          {v.name}
        </label>
      ))}

      {/* Table */}
      {selectedRows.length > 0 && (
        <>
          <h2>Comparison Table</h2>
          <table border="1" cellPadding="6">
            <thead>
              <tr>
                <th>Name</th>
                <th>Yield</th>
                <th>Maturity</th>
                <th>Seed</th>
                <th>Harvest</th>
                <th>Resistance %</th>
              </tr>
            </thead>
            <tbody>
              {selectedRows.map((v) => {
                const r = getResistance(v);
                return (
                  <tr key={v.name}>
                    <td
                      style={{ cursor: "pointer" }}
                      onClick={() =>
                        setActiveVariety(v)
                      }
                    >
                      {v.name}
                    </td>
                    <td>{v.yield_kg_ha ?? "—"}</td>
                    <td>{v.maturity_days ?? "—"}</td>
                    <td>{v.seed_weight_g ?? "—"}</td>
                    <td>{v.harvestability ?? "—"}</td>
                    <td>
                      {resistanceScore(r).toFixed(0)}%
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </>
      )}

      {/* Radar */}
      {selectedRows.length > 1 && (
        <>
          <h2>Trait Radar</h2>
          <ResponsiveContainer width="100%" height={400}>
            <RadarChart data={radarData}>
              <PolarGrid />
              <PolarAngleAxis dataKey="name" />
              <PolarRadiusAxis />
              <Radar
                dataKey="Yield"
                stroke="#3498db"
                fill="#3498db"
                fillOpacity={0.3}
              />
              <Radar
                dataKey="Resistance"
                stroke="#e74c3c"
                fill="#e74c3c"
                fillOpacity={0.3}
              />
            </RadarChart>
          </ResponsiveContainer>
        </>
      )}

      {/* Heatmap */}
      {selectedRows.length > 0 && (
        <>
          <h2>Resistance Heatmap</h2>
          <HeatMap
            data={heatData}
            xLabels={diseases}
            yLabels={selectedRows.map((v) => v.name)}
            cellStyle={(bg, val) => ({
              background:
                val === 2
                  ? "#2ecc71"
                  : val === 0
                  ? "#e74c3c"
                  : "#bdc3c7",
            })}
          />
        </>
      )}

      {/* Scatter */}
      {selectedRows.length > 1 && (
        <>
          <h2>Scatter Comparison</h2>
          X:
          <select onChange={(e) => setXTrait(e.target.value)}>
            <option value="yield_kg_ha">Yield</option>
            <option value="maturity_days">Maturity</option>
            <option value="seed_weight_g">Seed weight</option>
            <option value="harvestability">Harvestability</option>
          </select>
          Y:
          <select onChange={(e) => setYTrait(e.target.value)}>
            <option value="maturity_days">Maturity</option>
            <option value="yield_kg_ha">Yield</option>
            <option value="seed_weight_g">Seed weight</option>
            <option value="harvestability">Harvestability</option>
          </select>

          <ResponsiveContainer width="100%" height={350}>
            <ScatterChart>
              <CartesianGrid />
              <XAxis dataKey="x" />
              <YAxis dataKey="y" />
              <Tooltip />
              <Scatter data={scatterData} fill="#3498db" />
            </ScatterChart>
          </ResponsiveContainer>
        </>
      )}

      {/* Modal */}
      {activeVariety && (
        <div
          onClick={() => setActiveVariety(null)}
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              background: "white",
              padding: 30,
              width: 600,
            }}
          >
            <h2>{activeVariety.name}</h2>
            <pre>
              {JSON.stringify(activeVariety, null, 2)}
            </pre>
            <button
              onClick={() => setActiveVariety(null)}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}